//! Commander precons: the Commander decks in MTGJSON's deck list
//! (<https://mtgjson.com/api/v5/DeckList.json>, built from Wizards of the
//! Coast's published decklists), and importing one as a new deck.
//!
//! The list is cached for twelve hours. Each precon's color identity comes
//! from `priv/data/precon_colors.json` (regenerated by
//! `scripts/precon-colors.mjs`), since the deck list has no colors and deck
//! files are large; precons newer than that snapshot have their deck files
//! fetched when the list is built. A deck file names each card's
//! Scryfall printing and whether the precon's copy is foil or etched. The
//! new deck is a plain Commander deck that can be edited.
//! With `add_to_collection`, each card in the command zone and main deck
//! becomes a collection item of the precon's printing and finish (stored in
//! the chosen location) and is allocated to the deck, all in the deck's
//! creation transaction. Basic lands are skipped: decks count them as
//! allocated without copies.

use std::collections::HashMap;
use std::sync::LazyLock;
use std::time::Duration;

use async_graphql::MaybeUndefined;
use futures_util::{StreamExt, stream};
use lotus::decklist::{Entry, FetchError};
use lotus::{Finish, Quantity, Zone};
use serde::de::DeserializeOwned;
use serde::{Deserialize, Serialize};
use sqlx::{SqliteConnection, SqlitePool};

use crate::collection::changes::{self, ItemChanges, ItemError};
use crate::decks::DeckError;
use crate::decks::external::{self, SyncError};
use crate::decks::model::{CollectionItemId, DeckCardId, DeckId, DeckRow, load_deck_on};
use crate::decks::records::{self, DeckChanges};
use manavault_catalog::pricing::PriceStore;
use manavault_core::db;
use manavault_core::state::AppState;

/// The MTGJSON deck type of Commander precons.
const COMMANDER_DECK: &str = "Commander Deck";
const CACHE_KEY: &str = "mtgjson:commander_precons";
const CACHE_TTL: Duration = Duration::from_secs(12 * 60 * 60);
/// Deck files fetched at once for precons missing from the snapshot.
const COLOR_FETCHES: usize = 8;

const COLORS_DATA: &str = include_str!("../../../../../priv/data/precon_colors.json");

#[derive(Deserialize)]
struct ColorsFile {
    decks: HashMap<String, Vec<String>>,
}

/// Color identities by precon id, from the snapshot.
static SNAPSHOT_COLORS: LazyLock<HashMap<String, Vec<String>>> = LazyLock::new(|| {
    serde_json::from_str::<ColorsFile>(COLORS_DATA).map_or_else(
        |error| {
            tracing::error!(%error, "priv/data/precon_colors.json is unreadable");
            HashMap::new()
        },
        |file| file.decks,
    )
});

/// One precon in the list.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Precon {
    /// MTGJSON's deck file name, such as `SubjectiveReality_C18`.
    pub id: String,
    /// The deck's name, such as `Subjective Reality`.
    pub name: String,
    /// The product's set name, such as `Commander 2018`, when the catalog
    /// knows the set.
    pub product: Option<String>,
    /// `YYYY-MM-DD`.
    pub release_date: Option<String>,
    /// Wizards of the Coast's decklist article.
    pub url: Option<String>,
    /// The commanders' color identity in WUBRG order, `["C"]` when
    /// colorless; `None` when the deck file could not be read or lists no
    /// commander.
    pub color_identity: Option<Vec<String>>,
}

#[derive(Deserialize)]
struct Wrapped<T> {
    data: T,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ListedDeck {
    code: String,
    file_name: String,
    name: String,
    #[serde(default)]
    release_date: Option<String>,
    #[serde(default)]
    source: Option<String>,
    #[serde(rename = "type")]
    kind: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DeckFile {
    name: String,
    #[serde(default)]
    commander: Vec<DeckFileCard>,
    #[serde(default)]
    main_board: Vec<DeckFileCard>,
    #[serde(default)]
    side_board: Vec<DeckFileCard>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DeckFileCard {
    name: String,
    count: i64,
    #[serde(default)]
    is_foil: bool,
    #[serde(default)]
    is_etched: bool,
    #[serde(default)]
    identifiers: Identifiers,
    #[serde(default)]
    color_identity: Vec<String>,
}

#[derive(Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Identifiers {
    #[serde(default)]
    scryfall_id: Option<String>,
}

impl DeckFileCard {
    fn entry(&self, zone: Zone) -> Option<Entry> {
        let mut entry = Entry::from_source(
            Some(self.name.clone()),
            Some(self.count),
            zone,
            self.identifiers.scryfall_id.clone(),
        )?;
        entry.finish = if self.is_etched {
            Finish::Etched
        } else if self.is_foil {
            Finish::Foil
        } else {
            Finish::Nonfoil
        };
        Some(entry)
    }
}

impl DeckFile {
    fn entries(&self) -> Vec<Entry> {
        [
            (&self.commander, Zone::Commander),
            (&self.main_board, Zone::Mainboard),
            (&self.side_board, Zone::Considering),
        ]
        .into_iter()
        .flat_map(|(cards, zone)| cards.iter().filter_map(move |card| card.entry(zone)))
        .collect()
    }

    /// The union of the commanders' color identities, as in the snapshot.
    fn color_identity(&self) -> Option<Vec<String>> {
        if self.commander.is_empty() {
            return None;
        }
        let colors: Vec<String> = ["W", "U", "B", "R", "G"]
            .into_iter()
            .filter(|color| {
                self.commander
                    .iter()
                    .any(|card| card.color_identity.iter().any(|own| own == color))
            })
            .map(str::to_owned)
            .collect();
        Some(if colors.is_empty() {
            vec!["C".to_owned()]
        } else {
            colors
        })
    }
}

fn request_error(error: &reqwest::Error) -> FetchError {
    if error.is_timeout() {
        FetchError::Timeout
    } else {
        FetchError::RequestFailed
    }
}

/// GETs `path` under the MTGJSON API base and decodes its `data`.
async fn get_data<T: DeserializeOwned>(state: &AppState, path: &[&str]) -> Result<T, FetchError> {
    let mut url = reqwest::Url::parse(&state.config.platform_urls.mtgjson_api)
        .map_err(|_| FetchError::RequestFailed)?;
    url.path_segments_mut()
        .map_err(|()| FetchError::RequestFailed)?
        .pop_if_empty()
        .extend(path);
    let response = state
        .http
        .get(url)
        .header(reqwest::header::ACCEPT, "application/json")
        .send()
        .await
        .map_err(|error| request_error(&error))?;
    match response.status().as_u16() {
        200..=299 => {}
        401 | 403 => return Err(FetchError::Forbidden),
        404 => return Err(FetchError::NotFound),
        status => return Err(FetchError::HttpStatus(status)),
    }
    let body = response
        .bytes()
        .await
        .map_err(|error| request_error(&error))?;
    serde_json::from_slice::<Wrapped<T>>(&body)
        .map(|wrapped| wrapped.data)
        .map_err(|_| FetchError::InvalidJson)
}

/// Set names by lowercase code, from the catalog's Scryfall set list.
async fn set_names(
    pool: &SqlitePool,
) -> Result<std::collections::HashMap<String, String>, sqlx::Error> {
    Ok(sqlx::query!(
        r#"SELECT code AS "code!", name AS "name!" FROM scryfall_sets WHERE name IS NOT NULL"#
    )
    .fetch_all(pool)
    .await?
    .into_iter()
    .map(|row| (row.code, row.name))
    .collect())
}

/// Every precon, newest first, then by name; cached for twelve hours.
pub async fn list(state: &AppState) -> Result<Vec<Precon>, SyncError> {
    if let Some(cached) = state.cache_get::<Vec<Precon>>(CACHE_KEY).await {
        return Ok(cached);
    }
    let decks: Vec<ListedDeck> = get_data(state, &["DeckList.json"])
        .await
        .map_err(SyncError::Fetch)?;
    let sets = set_names(&state.db).await?;
    let mut precons: Vec<Precon> = decks
        .into_iter()
        .filter(|deck| deck.kind == COMMANDER_DECK)
        .map(|deck| Precon {
            product: sets.get(&deck.code.to_lowercase()).cloned(),
            color_identity: SNAPSHOT_COLORS.get(&deck.file_name).cloned(),
            id: deck.file_name,
            name: deck.name,
            release_date: deck.release_date,
            url: deck.source,
        })
        .collect();
    fetch_missing_colors(state, &mut precons).await;
    // ISO dates order as text; undated decks go last.
    precons.sort_by(|a, b| {
        b.release_date
            .cmp(&a.release_date)
            .then_with(|| a.name.cmp(&b.name))
    });
    // An empty list means a broken response; ask again next time instead of
    // serving it for hours.
    if !precons.is_empty() {
        state.cache_put(CACHE_KEY, &precons, CACHE_TTL).await;
    }
    Ok(precons)
}

/// Reads the color identity of precons newer than the snapshot from their
/// deck files. One that fails stays without colors until the list is next
/// built.
async fn fetch_missing_colors(state: &AppState, precons: &mut [Precon]) {
    let missing: Vec<(usize, String)> = precons
        .iter()
        .enumerate()
        .filter(|(_, precon)| precon.color_identity.is_none())
        .map(|(index, precon)| (index, format!("{}.json", precon.id)))
        .collect();
    let fetched: Vec<(usize, Option<Vec<String>>)> = stream::iter(missing)
        .map(|(index, file_name)| async move {
            match get_data::<DeckFile>(state, &["decks", &file_name]).await {
                Ok(deck) => (index, deck.color_identity()),
                Err(error) => {
                    tracing::warn!(%error, file_name, "could not read a precon's colors");
                    (index, None)
                }
            }
        })
        .buffer_unordered(COLOR_FETCHES)
        .collect()
        .await;
    for (index, colors) in fetched {
        if let Some(precon) = precons.get_mut(index) {
            precon.color_identity = colors;
        }
    }
}

/// What to import.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PreconImport {
    /// Moxfield's public deck id.
    pub precon_id: String,
    /// The new deck's name; the precon's own name when blank.
    pub name: Option<String>,
    pub add_to_collection: bool,
    /// Where added copies are stored (and return to when released).
    pub location_id: Option<i64>,
}

/// A finished import.
#[derive(Debug, Clone)]
pub struct Imported {
    pub deck: DeckRow,
    /// Names that matched no card in the catalog.
    pub unresolved: Vec<String>,
    /// Copies added to the collection and allocated to the deck.
    pub added_to_collection: u32,
}

/// Imports a precon as a new deck, optionally adding its cards to the
/// collection and allocating them. Nothing is written when any step fails.
pub async fn import(state: &AppState, input: &PreconImport) -> Result<Imported, SyncError> {
    // Only listed precons: the id becomes part of the request path.
    let precon_id = input.precon_id.trim();
    if !list(state)
        .await?
        .iter()
        .any(|precon| precon.id == precon_id)
    {
        return Err(DeckError::Message("Choose a precon from the list.".to_owned()).into());
    }
    let location_id = if input.add_to_collection {
        input.location_id
    } else {
        None
    };
    if let Some(location_id) = location_id {
        ensure_storage_location(&state.db, location_id).await?;
    }
    let file_name = format!("{precon_id}.json");
    let deck: DeckFile = get_data(state, &["decks", &file_name])
        .await
        .map_err(SyncError::Fetch)?;
    let name = input
        .name
        .as_deref()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map_or_else(|| deck.name.clone(), str::to_owned);

    let entries = deck.entries();

    let mut tx = db::begin_write(&state.db).await?;
    let deck = records::create_deck_in(
        &mut tx,
        &DeckChanges {
            name: Some(Some(name)),
            format: Some(Some("commander".to_owned())),
            ..DeckChanges::default()
        },
    )
    .await?;
    let unresolved = external::write_entries(&mut tx, &state.db, deck.id, &entries).await?;
    let added_to_collection = if input.add_to_collection {
        add_to_collection(&mut tx, &state.prices, deck.id, location_id).await?
    } else {
        0
    };
    let deck = load_deck_on(&mut tx, deck.id)
        .await?
        .ok_or(DeckError::DeckNotFound)?;
    tx.commit().await?;
    Ok(Imported {
        deck,
        unresolved,
        added_to_collection,
    })
}

/// Allocated copies leave their location, so a list location (wanted
/// cards) cannot hold them.
async fn ensure_storage_location(pool: &SqlitePool, id: i64) -> Result<(), DeckError> {
    let kind: Option<String> =
        sqlx::query_scalar!(r#"SELECT kind AS "kind!" FROM locations WHERE id = ?1"#, id)
            .fetch_optional(pool)
            .await?;
    match kind.as_deref() {
        None => Err(DeckError::Message("Location was not found.".to_owned())),
        Some("list") => Err(DeckError::Message(
            "List locations hold wanted cards; choose where the precon's cards are stored."
                .to_owned(),
        )),
        Some(_) => Ok(()),
    }
}

fn item_error(error: ItemError) -> DeckError {
    match error {
        ItemError::Db(error) => DeckError::Db(error),
        other => DeckError::Message(other.to_string()),
    }
}

/// Adds a collection item for each command zone and main deck card (basic
/// lands excepted) and allocates it; returns the number of copies.
async fn add_to_collection(
    conn: &mut SqliteConnection,
    prices: &PriceStore,
    deck_id: DeckId,
    location_id: Option<i64>,
) -> Result<u32, DeckError> {
    let considering = Zone::Considering.as_str();
    // A card whose precon printing is not in the catalog gets its newest
    // English printing.
    let rows = sqlx::query!(
        r#"SELECT dc.id AS "id!: DeckCardId", dc.quantity AS "quantity!: i64",
                  dc.finish AS "finish!", c.type_line,
                  COALESCE(dc.preferred_printing_id,
                    (SELECT p.scryfall_id FROM scryfall_printings p
                     WHERE p.oracle_id = dc.oracle_id
                     ORDER BY p.lang = 'en' DESC, p.released_at DESC, p.scryfall_id
                     LIMIT 1)) AS "printing: String"
           FROM deck_cards dc JOIN scryfall_cards c ON c.oracle_id = dc.oracle_id
           WHERE dc.deck_id = ?1 AND dc.zone != ?2
           ORDER BY dc.id"#,
        deck_id,
        considering
    )
    .fetch_all(&mut *conn)
    .await?;
    let mut copies: u32 = 0;
    for row in rows {
        if row.type_line.as_deref().is_some_and(lotus::is_basic_land) {
            continue;
        }
        let (Some(printing), Some(quantity)) = (
            row.printing,
            u32::try_from(row.quantity).ok().and_then(Quantity::new),
        ) else {
            continue;
        };
        let finish = Finish::parse(&row.finish).unwrap_or(Finish::Nonfoil);
        let item = changes::create_in(
            conn,
            prices,
            ItemChanges {
                scryfall_id: MaybeUndefined::Value(printing),
                quantity: MaybeUndefined::Value(row.quantity),
                finish: MaybeUndefined::Value(finish.as_str().to_owned()),
                location_id: location_id.map_or(MaybeUndefined::Undefined, MaybeUndefined::Value),
                ..ItemChanges::default()
            },
        )
        .await
        .map_err(item_error)?;
        manavault_allocation::allocate_in(conn, row.id, CollectionItemId(item), quantity).await?;
        copies = copies.saturating_add(quantity.get());
    }
    Ok(copies)
}
